const host = globalThis.__verifyHost;
if (!host) return false;
if (host.zoom !== 1) return false;
if (host.zoomCalls.length !== 0) return false;
return true;

const p = document.getElementById('lead-paragraph');
const h1 = document.querySelector('h1');
const h2 = document.querySelector('h2');
const h3 = document.querySelector('h3');
const badge = document.querySelector('.px-sized-badge');
if (!p || !h1 || !h2 || !h3 || !badge) return false;

const pFs = parseFloat(window.getComputedStyle(p).fontSize);
const h1Fs = parseFloat(window.getComputedStyle(h1).fontSize);
const h2Fs = parseFloat(window.getComputedStyle(h2).fontSize);
const h3Fs = parseFloat(window.getComputedStyle(h3).fontSize);
const badgeFs = parseFloat(window.getComputedStyle(badge).fontSize);

// Baseline: p=16px (-> 24), h1=32px (-> 48), h2=24px (-> 36), h3=20px (-> 30), badge=20px (-> 30)
if (Math.abs(pFs - 24) > 0.5) return false;
if (Math.abs(h1Fs - 48) > 1.0) return false;
if (Math.abs(h2Fs - 36) > 0.5) return false;
if (Math.abs(h3Fs - 30) > 0.5) return false;
if (Math.abs(badgeFs - 30) > 0.5) return false;
return true;

const p = document.getElementById('lead-paragraph');
if (!p) return false;
const cs = window.getComputedStyle(p);
const lh = parseFloat(cs.lineHeight);
const fs = parseFloat(cs.fontSize);
if (Math.abs(lh / fs - 1.8) > 0.1) return false;

// Fixed card was allowed to grow: scrollHeight <= clientHeight + 1
const fixedCard = document.getElementById('fixed-card');
if (!fixedCard) return false;
if (fixedCard.scrollHeight > fixedCard.clientHeight + 1) return false;

// All elements in main have no text cut off
for (const el of document.querySelectorAll('main *')) {
  if (el.scrollHeight > el.clientHeight + 1) return false;
}
return true;

const p = document.getElementById('lead-paragraph');
if (!p) return false;

// Alt+Shift+Equal -> 160% (16 * 1.6 = 25.6px)
await __verifyPress('Alt+Shift+Equal');
let pFs = parseFloat(window.getComputedStyle(p).fontSize);
if (Math.abs(pFs - 25.6) > 0.5) return false;

// Alt+Shift+Minus -> 150% (24px)
await __verifyPress('Alt+Shift+Minus');
pFs = parseFloat(window.getComputedStyle(p).fontSize);
if (Math.abs(pFs - 24) > 0.5) return false;

return true;
